import{_ as o,a0 as r,w as p,s as l,I as e,x as a,a1 as s,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"用 Portainer.io 來監控和管理 Docker 容器（2） | LCTT x X-CMD","titleTemplate":false,"description":"用 Portainer.io 來監控和管理 Docker 容器（2） | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Portainer.io 來監控和管理 Docker 容器（2） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Portainer.io 來監控和管理 Docker 容器（2） | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2","title":"用 Portainer.io 來監控和管理 Docker 容器（2）","tag":"202101","desc":""},"relativePath":"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2.md","filePath":"[post].md"}'),d={name:"202101/20190516 Monitor and Manage Docker Containers with Portainer.io (GUI tool) - Part-2.md"};function h(u,t,g,m,w,x){const n=r("Link");return p(),l("div",null,[t[18]||(t[18]=e("h1",{id:"用-portainer-io-來監控和管理-docker-容器-2",tabindex:"-1"},[a("用 Portainer.io 來監控和管理 Docker 容器（2） "),e("a",{class:"header-anchor",href:"#用-portainer-io-來監控和管理-docker-容器-2","aria-label":"Permalink to “用 Portainer.io 來監控和管理 Docker 容器（2）”"},"​")],-1)),t[19]||(t[19]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202101/14/204401knuxjru53n5su6ns.jpg",alt:""})],-1)),e("p",null,[t[1]||(t[1]=a("作為",-1)),s(n,{href:"https://linux.cn/article-12634-1.html"},{default:i(()=>[...t[0]||(t[0]=[a("第 1 部分",-1)])]),_:1}),t[2]||(t[2]=a("的延續，本第 2 部分將介紹 Portainer 的其餘功能。",-1))]),t[20]||(t[20]=c(`<h3 id="監控-docker-容器鏡像" tabindex="-1">監控 docker 容器鏡像 <a class="header-anchor" href="#監控-docker-容器鏡像" aria-label="Permalink to “監控 docker 容器鏡像”">​</a></h3><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$ docker ps -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND             CREATED             STATUS   PORTS                             NAMES</span></span>
<span class="line"><span>9ab9aa72f015        ubuntu                &quot;/bin/bash&quot;         14 seconds ago      Exited (0) 12 seconds ago                  suspicious_shannon</span></span>
<span class="line"><span>305369d3b2bb        centos                &quot;/bin/bash&quot;         24 seconds ago      Exited (0) 22 seconds ago                  admiring_mestorf</span></span>
<span class="line"><span>9a669f3dc4f6        portainer/portainer   &quot;/portainer&quot;        7 minutes ago       Up 7 minutes   0.0.0.0:9000-&gt;9000/tcp      trusting_keller</span></span></code></pre></div><p>包括 <code>portainer</code>（docker 容器鏡像），所有已退出和當前正在運行的 docker 鏡像都會顯示出來。下面的 Portainer GUI 屏幕截圖顯示了相同的情況。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Docker_status-1024x423.jpg" alt="Docker_status"></p><h3 id="監視事件" tabindex="-1">監視事件 <a class="header-anchor" href="#監視事件" aria-label="Permalink to “監視事件”">​</a></h3><p>單擊 portainer 網頁中的“Events”選項，如下所示。</p><p>基於 docker 容器活動生成和創建的各種事件將被提取並顯示在此頁面中.</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Events-1024x404.jpg" alt="Container-Events-Poratiner-GUI"></p><p>現在檢查並驗證“Events”部分是如何工作的。創建一個新的 docker 容器鏡像 <code>redis</code>，如下所述，在 docker 命令列檢查狀態：<code>docker ps –a</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$ docker ps -a</span></span>
<span class="line"><span>CONTAINER ID        IMAGE                 COMMAND                  CREATED              STATUS         PORTS                    NAMES</span></span>
<span class="line"><span>cdbfbef59c31        redis                 &quot;docker-entrypoint.s…&quot;   About a minute ago   Up About a minute         6379/tcp                 angry_varahamihira</span></span>
<span class="line"><span>9ab9aa72f015        ubuntu                &quot;/bin/bash&quot;              10 minutes ago       Exited (0) 10 minutes ago                            suspicious_shannon</span></span>
<span class="line"><span>305369d3b2bb        centos                &quot;/bin/bash&quot;              11 minutes ago       Exited (0) 11 minutes ago                            admiring_mestorf</span></span>
<span class="line"><span>9a669f3dc4f6        portainer/portainer   &quot;/portainer&quot;             17 minutes ago       Up 17 minutes         0.0.0.0:9000-&gt;9000/tcp   trusting_keller</span></span></code></pre></div><p>單擊頂部的“Event List”刷新事件列表，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/events_updated-1024x414.jpg" alt="events_updated"></p><p>現在事件的頁面也更新了這個變化，</p><h3 id="主機狀態" tabindex="-1">主機狀態 <a class="header-anchor" href="#主機狀態" aria-label="Permalink to “主機狀態”">​</a></h3><p>下面是 portainer 顯示主機狀態的屏幕截圖。這是一個簡單的窗口。這顯示了主機 Linux 機器的基本信息，如“CPU”、“主機名”、“操作系統信息”等。這個頁面在不需要登錄主機命令列的情況下提供了非常有用的信息，以便快速瀏覽。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Host_names-1024x408.jpg" alt="Host-names-Portainer"></p><h3 id="portainer-中的儀表板" tabindex="-1">Portainer 中的儀表板 <a class="header-anchor" href="#portainer-中的儀表板" aria-label="Permalink to “Portainer 中的儀表板”">​</a></h3><p>到目前為止，我們已經在“Local”部分看到了基於 portainer 的各種特性。現在跳到所選 Docker 容器鏡像的“Dashboard”部分。</p><p>在 Portainer 的網頁中單擊“EndPoint”選項時，會出現以下窗口：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/End_Point_Settings-1024x471.jpg" alt="End_Point_Settings"></p><p>對於主機容器鏡像，此儀表板有許多狀態和選項。</p><h4 id="stacks" tabindex="-1">Stacks <a class="header-anchor" href="#stacks" aria-label="Permalink to “Stacks”">​</a></h4><p>單擊此選項可提供任何堆棧（如果有的話）的狀態。因為這裏沒有堆棧，所以顯示為零。</p><h4 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to “Images”">​</a></h4><p>單擊此選項可提供主機中可用的容器鏡像。此選項將顯示所有活動和退出的容器鏡像。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Images-1024x398.jpg" alt="Docker-Container-Images-Portainer"></p><p>例如，再創建一個“Nginx”容器並刷新此列表以查看更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@linuxtechi ~}$  sudo docker run nginx</span></span>
<span class="line"><span>Unable to find image &#39;nginx:latest&#39; locally</span></span>
<span class="line"><span>latest: Pulling from library/nginx</span></span>
<span class="line"><span>27833a3ba0a5: Pull complete</span></span>
<span class="line"><span>ea005e36e544: Pull complete</span></span>
<span class="line"><span>d172c7f0578d: Pull complete</span></span>
<span class="line"><span>Digest: sha256:e71b1bf4281f25533cf15e6e5f9be4dac74d2328152edf7ecde23abc54e16c1c</span></span>
<span class="line"><span>Status: Downloaded newer image for nginx:latest</span></span></code></pre></div><p>下面是刷新後的鏡像界面：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Nginx_Image_creation-1024x439.jpg" alt="Nginx_Image_creation"></p><p>當 Nginx 鏡像處於 <code>stopped</code>/<code>killed</code> 狀態時，docker 的容器鏡像會改變為 <code>unused</code> 狀態。</p><p><strong>注</strong>：你可以看到這裏所有的鏡像的細節都非常清楚，比如內存使用，創建日期和時間。與命令列選項相比，從這裏維護和監視容器將非常容易。</p><h4 id="networks" tabindex="-1">Networks <a class="header-anchor" href="#networks" aria-label="Permalink to “Networks”">​</a></h4><p>此選項用於網絡操作。例如分配 IP 地址、創建子網、提供 IP 地址範圍、訪問控制（管理員和普通用户）。下面的窗口提供了各種可能選項的詳細信息。根據你的需要，可以進一步去自行研究這些選項。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Network-1024x463.jpg" alt="Conatiner-Network-Portainer"></p><p>輸入所有各種網絡參數後，單擊“create network”按鈕即可創建網絡。</p><h4 id="container" tabindex="-1">Container <a class="header-anchor" href="#container" aria-label="Permalink to “Container”">​</a></h4><p>此選項將提供容器狀態。此列表將提供有關活動的和未運行的容器狀態的詳細信息。此輸出類似於 docker ps 命令選項。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Containers-1024x364.jpg" alt="Containers-Status-Portainer"></p><p>在該窗口中，通過選中複選框並選擇上述按鈕可以根據需要控制容器停止和啓動。一個例子如下：</p><p>例如，“CentOS”和“Ubuntu”容器都處於停止狀態，現在可以通過選中複選框並點擊“Start”按鈕來啓動它們。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers1-1024x432.jpg" alt="start_containers1"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers2-1024x307.jpg" alt="start_containers2"></p><p><strong>注意：</strong> 因為這兩個都是 Linux 容器鏡像，所以不會被啓動。Portainer 嘗試啓動，但稍後又停止。試試啓動“Nginx”，你會看到它變成了 <code>running</code> 狀態。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/start_containers3-1024x435.jpg" alt="start_containers3"></p><h4 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to “Volume”">​</a></h4><p>參見本文章第一部分。</p><h3 id="portainer-中的設置選項" tabindex="-1">Portainer 中的設置選項 <a class="header-anchor" href="#portainer-中的設置選項" aria-label="Permalink to “Portainer 中的設置選項”">​</a></h3><p>到目前為止，我們已經在“Local”部分看到了基於 portainer 的各種特性。現在跳到所選 Docker 容器圖像的“Settings”部分。</p><p>在 Portainer 的網頁中單擊“Settings”選項時，可以使用以下的配置選項：</p><h4 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to “Extensions”">​</a></h4><p>這是一個簡單的 Portainer CE 訂閲程序。詳細信息和用途可以從附加的窗口中看到。這主要用於維護相應版本的許可證和訂閲。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Extensions-1024x421.jpg" alt="Extensions"></p><h4 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to “Users”">​</a></h4><p>此選項用於添加具有或不具有管理權限的“用户”。下面的示例提供了相同的示例。</p><p>在本例中輸入你的想好的用户名比如“shashi”和你選擇的密碼，然後點擊下面的“Create User”按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/create_user-1024x350.jpg" alt="create_user_portainer"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/create_user2-1024x372.jpg" alt="create_user2_portainer"></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Internal-user-Portainer-1024x257.jpg" alt="Internal-user-Portainer"></p><p>類似地，可以通過選中複選框並點擊 “remove” 按鈕來刪除剛剛創建的用户“shashi”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/user_remove-1024x318.jpg" alt="user_remove_portainer"></p><h4 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to “Endpoints”">​</a></h4><p>此選項用於端點終端管理。終端可以添加和刪除，如附加窗口中所示。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Endpoint-1024x349.jpg" alt="Endpoint-Portainer-GUI"></p><p>新終端“shashi”是使用如下所示的各種默認參數創建的，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Endpoint2-1024x379.jpg" alt="Endpoint2-Portainer-GUI"></p><p>類似地，可以通過單擊複選框並單擊移除按鈕來移除此端點。</p><h4 id="registries" tabindex="-1">Registries <a class="header-anchor" href="#registries" aria-label="Permalink to “Registries”">​</a></h4><p>此選項用於註冊管理。由於 docker hub 有各種鏡像的註冊，因此此功能可用於類似的目的。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Registry-1024x420.jpg" alt="Registry-Portainer-GUI"></p><p>使用默認選項就可以創建“shashi-registry”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Registry2-1024x409.jpg" alt="Registry2-Portainer-GUI"></p><p>同樣，如果不需要了，就可以移除它。</p><h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h4><p>此選項用於設置以下各種選項，</p><ul><li>設置快照間隔</li><li>設置自定義徽標</li><li>創建外部模板</li><li>安全功能，如：為非管理員禁用和啓用 bin 掛載，為非管理員禁用/啓用權限，啓用主機管理功能</li></ul><p>下面的屏幕截圖顯示了出於演示目的啓用和禁用的一些選項。一旦全部完成點擊“保存設置”按鈕保存所有這些選項。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Portainer-GUI-Settings-1024x418.jpg" alt="Portainer-GUI-Settings"></p><p>現在點開“Authentication settings”就會彈出 LDAP、Internal 和 OAuth（extension）選項，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/05/Authentication-Portainer-GUI-Settings-1024x344.jpg" alt="Authentication-Portainer-GUI-Settings"></p><p>根據我們想要的環境安全特性級別，選擇相應的選項。</p><p>以上就是本文的內容，我希望這些介紹 portainer 的文章能幫助你更有效地管理和監視容器。請分享你的反饋和意見。</p><hr>`,83)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),s(n,{href:"https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/"},{default:i(()=>[...t[3]||(t[3]=[a("https://www.linuxtechi.com/monitor-manage-docker-containers-portainer-io-part-2/",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=a("作者：",-1)),s(n,{href:"https://www.linuxtechi.com/author/shashidhar/"},{default:i(()=>[...t[5]||(t[5]=[a("Shashidhar Soppin",-1)])]),_:1}),t[10]||(t[10]=a(" 選題：",-1)),s(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[6]||(t[6]=[a("lujun9972",-1)])]),_:1}),t[11]||(t[11]=a(" 譯者：",-1)),s(n,{href:"https://github.com/Chao-zhi"},{default:i(()=>[...t[7]||(t[7]=[a("Chao-zhi",-1)])]),_:1}),t[12]||(t[12]=a(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[a("LCTT",-1)])]),_:1}),t[16]||(t[16]=a(" 原創編譯，",-1)),s(n,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[a("Linux中國",-1)])]),_:1}),t[17]||(t[17]=a(" 榮譽推出",-1))])])}const f=o(d,[["render",h]]);export{P as __pageData,f as default};
